pdb-metadata.query:
{entries(entry_ids:["7P48"]) {
  rcsb_id
  struct {title}
  rcsb_accession_info {major_revision minor_revision revision_date}
  rcsb_primary_citation {pdbx_database_id_PubMed pdbx_database_id_DOI year}
  polymer_entities {
    rcsb_id
    rcsb_polymer_entity {pdbx_description}
    entity_poly {rcsb_mutation_count}
    rcsb_polymer_entity_container_identifiers {
      reference_sequence_identifiers {database_name database_accession}
    }
    rcsb_entity_source_organism {ncbi_taxonomy_id scientific_name}
    entity_src_gen {
      pdbx_gene_src_gene gene_src_strain pdbx_gene_src_ncbi_taxonomy_id pdbx_gene_src_scientific_name
      pdbx_host_org_ncbi_taxonomy_id pdbx_host_org_scientific_name
    }
  }
}}
